"import shutil

import pandas as pd
from openpyxl import load_workbook

INPUT_FILE = "input.xlsx"
OUTPUT_FILE = "output.xlsx"
COMBINED_SHEET = "combined"
START_ROW = 2  # header lives in row 1; data must be written starting at A2


def normalize(value):
    """Normalize a header string for matching (case/whitespace-insensitive)."""
    if value is None:
        return None
    return " ".join(str(value).split()).lower()


def clean(value):
    """Convert pandas NaN/NaT values to None so openpyxl writes empty cells."""
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
    except (TypeError, ValueError):
        pass
    return value


def main():
    # Work on a copy of the provided input workbook.
    shutil.copyfile(INPUT_FILE, OUTPUT_FILE)

    wb = load_workbook(OUTPUT_FILE)

    # Ensure the 'combined' sheet exists (create it if the macro only made an empty one).
    if COMBINED_SHEET in wb.sheetnames:
        ws = wb[COMBINED_SHEET]
    else:
        ws = wb.create_sheet(COMBINED_SHEET)

    # Read the header row of the 'combined' sheet (row 1, columns A:O) and
    # build a lookup: header name -> column index in the combined sheet.
    header = [cell.value for cell in ws[1]]
    col_index = {}
    for i, name in enumerate(header, start=1):
        key = normalize(name)
        if key is not None and key not in col_index:
            col_index[key] = i

    if not col_index:
        raise ValueError("The 'combined' sheet has no header row to map columns to.")

    # Remove any stale data below the header before writing new data.
    if ws.max_row >= START_ROW:
        ws.delete_rows(START_ROW, ws.max_row - START_ROW + 1)

    # Load every sheet from the original workbook (first row of each = header).
    all_sheets = pd.read_excel(INPUT_FILE, sheet_name=None, header=0)

    frames = []
    for name, df in all_sheets.items():
        if normalize(name) == COMBINED_SHEET:
            continue  # skip the destination sheet itself
        df = df.dropna(how="all").dropna(axis=1, how="all")
        if df.empty:
            continue
        frames.append(df)

    if not frames:
        raise ValueError("No data found in the source sheets to combine.")

    # Stack all source sheets together, one below the other.
    combined = pd.concat(frames, ignore_index=True, sort=False)

    # Write the data starting at A2, placing each value in the column whose
    # header name matches (position/mapping driven by the 'combined' header).
    for offset, (_, record) in enumerate(combined.iterrows()):
        row_num = START_ROW + offset
        for col_name, value in record.items():
            idx = col_index.get(normalize(col_name))
            if idx is None:
                continue  # not part of the expected output header
            ws.cell(row=row_num, column=idx, value=clean(value))

    wb.save(OUTPUT_FILE)
    last_row = START_ROW + len(combined) - 1
    print(f"Combined {len(frames)} sheet(s), {len(combined)} data rows -> "
          f"'{COMBINED_SHEET}'!A{START_ROW}:O{last_row} in {OUTPUT_FILE}")


if __name__ == "__main__":
    main()"
